<?php
/**
 * Blocksy functions and definitions
 *
 * @link https://developer.wordpress.org/themes/basics/theme-functions/
 *
 * @package Blocksy
 */

if (version_compare(PHP_VERSION, '5.7.0', '<')) {
	require get_template_directory() . '/inc/php-fallback.php';
	return;
}

require get_template_directory() . '/inc/init.php';

/**
 * =========================================================
 * FURBUDDY: PERSONALIZACIONES CARRITO, CHECKOUT Y NAVIDAD
 * =========================================================
 */

// 1. Eliminar metodo de "Recogida local" (local pickup) en carrito y checkout
add_filter( 'woocommerce_package_rates', function( $rates ) {
	foreach ( $rates as $rate_id => $rate ) {
		if ( 'local_pickup' === $rate->method_id || false !== strpos( $rate_id, 'local_pickup' ) ) {
			unset( $rates[ $rate_id ] );
		}
	}
	return $rates;
}, 100, 1 );

// 2. Ocultar calculadora y selector de direccion en la pagina del carrito
add_filter( 'woocommerce_shipping_calculator_enable', '__return_false' );
add_filter( 'woocommerce_shipping_estimate_html', '__return_empty_string' );

// 3. Eliminar campo "Nombre de la empresa (opcional)" del checkout
add_filter( 'woocommerce_checkout_fields', function( $fields ) {
	if ( isset( $fields['billing']['billing_company'] ) ) {
		unset( $fields['billing']['billing_company'] );
	}
	return $fields;
} );

// 4. Cambiar texto "Shipment" por "Envio" en carrito y checkout
add_filter( 'woocommerce_shipping_package_name', function( $name, $i, $package ) {
	return 'Envio';
}, 10, 3 );

add_filter( 'gettext', function( $translated_text, $text, $domain ) {
	if ( 'woocommerce' === $domain && 'Shipment' === $text ) {
		return 'Envio';
	}
	return $translated_text;
}, 20, 3 );

/**
 * =========================================================
 * PASO 1: LOGO HEADER (OPCION 1) Y FAVICON GATITO NAVIDENO
 * =========================================================
 */
function furbuddy_navidad_logo_b64() {
	return '';
}

function furbuddy_navidad_fav_b64() {
	return '';
}

// Filtro Logo Blocksy
add_filter( 'get_custom_logo', function( $html ) {
	$logo = furbuddy_navidad_logo_b64();
	return sprintf(
		'<a href="%1$s" class="site-logo-container" rel="home"><img src="data:image/jpeg;base64,%2$s" class="default-logo furbuddy-navidad-logo" alt="Furbuddy Navideno" style="max-height: 70px; width: auto; object-fit: contain;" /></a>',
		esc_url( home_url( '/' ) ),
		$logo
	);
}, 999 );

add_filter( 'wp_get_attachment_image_src', function( $image, $attachment_id, $size, $icon ) {
	$logo_id = get_theme_mod( 'custom_logo' );
	if ( $logo_id && (int) $attachment_id === (int) $logo_id ) {
		return [
			'data:image/jpeg;base64,' . furbuddy_navidad_logo_b64(),
			460,
			257,
			false
		];
	}
	return $image;
}, 999, 4 );

// Filtro Favicon nativo WordPress
add_filter( 'get_site_icon_url', function( $url ) {
	return 'data:image/png;base64,' . furbuddy_navidad_fav_b64();
}, 999 );

add_filter( 'site_icon_attachment_image', function( $html ) {
	return '<link rel="icon" href="data:image/png;base64,' . furbuddy_navidad_fav_b64() . '" />';
}, 999 );

// Inyeccion directa en wp_head
add_action( 'wp_head', function() {
	$fav = furbuddy_navidad_fav_b64();
	$logo = furbuddy_navidad_logo_b64();
	?>
	<link rel="icon" type="image/png" href="data:image/png;base64,<?php echo $fav; ?>" />
	<link rel="shortcut icon" type="image/png" href="data:image/png;base64,<?php echo $fav; ?>" />
	<link rel="apple-touch-icon" href="data:image/png;base64,<?php echo $fav; ?>" />
	<style id="furbuddy-header-logo-css">
		.site-logo-container img,
		[data-id="logo"] img,
		.custom-logo-link img,
		.site-branding img {
			content: url("data:image/jpeg;base64,<?php echo $logo; ?>") !important;
			max-height: 65px !important;
			width: auto !important;
			object-fit: contain !important;
			display: inline-block !important;
		}
	</style>
	<script id="furbuddy-header-logo-js">
		document.addEventListener("DOMContentLoaded", function() {
			var newLogo = "data:image/jpeg;base64,<?php echo $logo; ?>";
			var imgs = document.querySelectorAll('.site-logo-container img, [data-id="logo"] img, .custom-logo-link img, .site-branding img');
			imgs.forEach(function(img) {
				img.src = newLogo;
				if (img.srcset) img.srcset = newLogo;
			});
		});
	</script>
	<?php
}, 999 );
